// 记录文件请求缓存 主线程使用的
if (!window._iidpPreloadLoaded) {
  window._iidpPreloadLoaded = new Map()
}

const __asyncLoadJsNew = (() => {
  // 正在加载或加载成功的存入此Map中
  const documentMap = new Map()

  return (url, crossOrigin, document = globalThis.document) => {
    let loaded = documentMap.get(document)
    if (!loaded) {
      loaded = new Map()
      documentMap.set(document, loaded)
    }

    // 正在加载或已经加载成功的，直接返回
    // console.log(' js inner == url ', url, loaded.get(url))
    if (loaded.get(url)) return loaded.get(url)

    const load = new Promise((resolve, reject) => {
      const script = document.createElement('script')
      script.type = 'text/javascript'
      if (crossOrigin) {
        script.crossOrigin = crossOrigin
      }
      script.src = url
      document.body.appendChild(script)
      script.onload = () => {
        resolve()
      }
      script.onerror = () => {
        reject(new Error('加载失败'))
      }
      setTimeout(() => {
        reject(new Error('timeout'))
      }, 60 * 1000)
    }).catch((err) => {
      // 加载失败的，从map中移除，第二次加载时，可以再次执行加载
      loaded.delete(url)
      window._iidpPreloadLoaded.delete(url)
      throw err
    })

    window._iidpPreloadLoaded.set(url, load)
    loaded.set(url, load)
    return loaded.get(url)
  }
})()
const __asyncLoadCssNew = (() => {
  // 正在加载或加载成功的存入此Map中
  const documentMap = new Map()

  return (url, document = globalThis.document) => {
    let loaded = documentMap.get(document)
    if (!loaded) {
      loaded = new Map()
      documentMap.set(document, loaded)
    }

    // 正在加载或已经加载成功的，直接返回
    // console.log(' css inner == url ', url, loaded.get(url))
    if (loaded.get(url)) return loaded.get(url)

    const load = new Promise((resolve, reject) => {
      const node = document.createElement('link')
      node.rel = 'stylesheet'
      node.href = url
      document.head.appendChild(node)
      node.onload = () => {
        resolve(true)
      }
      node.onerror = () => {
        reject(new Error('加载失败'))
      }
      setTimeout(() => {
        reject(new Error('timeout'))
      }, 60 * 1000)
    }).catch((err) => {
      // 加载失败的，从map中移除，第二次加载时，可以再次执行加载
      loaded.delete(url)
      window._iidpPreloadLoaded.delete(url)
      throw err
    })

    window._iidpPreloadLoaded.set(url, load)
    loaded.set(url, load)
    return loaded.get(url)
  }
})()

// console.log(' ============= in iidpPreload.js ')
const iidpPreloadRun = async () => {
  const pathMap = new Map()
  // fetch请求
  const getFetch = (url) => {
    return new Promise((resolve, reject) => {
      try {
        fetch(url)
          .then(function (response) {
            try {
              const headers = response.headers
              if (!window.tech) {
                window.tech = {}
              }
              let sessionAllowConcatResource =
                sessionStorage?.getItem?.('concatRes') ||
                sessionStorage?.getItem?.('allowConcatResource')
              // 标识开启 openResty的资源合并 sessionStorage 若有配置则concat优先
              if (sessionAllowConcatResource !== null && sessionAllowConcatResource !== undefined) {
                window.tech.allowConcatResource =
                  sessionAllowConcatResource === 'true' || sessionAllowConcatResource === true
                    ? true
                    : false
              } else if (
                headers.get('allow-concat-resource') ||
                headers.get('Allow-Concat-Resource')
              ) {
                window.tech.allowConcatResource = true // 标识开启 openResty的资源合并
              }
            } catch (e) {}
            return response.json()
          })
          .then(function (json) {
            resolve(json)
          })
          .catch(function (err) {
            console.log(' === iidpPreload  getFetch error2 ==', err, url)
            resolve()
            // reject(err);
          })
      } catch (e) {
        console.log(' === iidpPreload  getFetch error ==', e)
        resolve()
      }
    })
  }
  // 每100ms轮询等待 window.iidpSwRegistration 注册完成 10秒超时
  const pollWaitSw = () => {
    return new Promise((resolve, reject) => {
      let timeoutId
      const startTime = Date.now()
      const checkRegistration = () => {
        if (window.iidpSwRegistration) {
          clearTimeout(timeoutId)
          resolve()
        } else if (Date.now() - startTime >= 10000) {
          // 10秒超时
          reject(new Error('等待 ServiceWorker 注册超时'))
        } else {
          setTimeout(checkRegistration, 100)
        }
      }
      checkRegistration()
    })
  }
  const swReqConcatRes = (swConcatPaths) => {
    try {
      return new Promise((resolve) => {
        let baseUrl = location.origin
        let pre = ''
        try {
          let curUrl = new URL(location.href)
          let topParams = new URLSearchParams(curUrl.search)
          let srcFrontHost = topParams.get('frontHost')
          if (srcFrontHost) {
            // 若有frontHost配置 则再请求一次frontHost的的apps.json 为了获取判断是否开启 openResty的资源合并标识 Allow-Concat-Resource
            srcFrontHost = decodeURIComponent(srcFrontHost)
            pre = '//' + srcFrontHost
            baseUrl = location.protocol + '//' + srcFrontHost.split('/')[0]
          }
        } catch (e) {}
        const pendingRequests = new Map()
        // 如果已存在监听器，先移除旧的
        if (window.tech.__preLoadSwMessageListener) {
          navigator.serviceWorker.removeEventListener(
            'message',
            window.tech.__preLoadSwMessageListener
          )
          window.tech.__preLoadSwMessageListener = null
        }
        // 创建新的监听器并保存到全局变量
        window.tech.__preLoadSwMessageListener = (event) => {
          const { id, result, error, evalPaths } = event.data
          if (error) {
            reject(new Error(error))
          }
          // console.log(' === swMessageListener === ', event.data)
          if (evalPaths) {
            // // console.log(' ==== get evalPaths === ', evalPaths)
            // try {
            //   evalPaths.map((it) => {
            //     if (it.endsWith('.js')) {
            //       let jsPath = pre + pathMap.get(it)
            //       if (jsPath) {
            //         // 只能配置一些没有 app js 里面没有多语言变量定义的
            //         __asyncLoadJsNew(jsPath, document)
            //       }
            //     } else if (it.endsWith('.css')) {
            //       let cssPath = pre + pathMap.get(it)
            //       if (cssPath) {
            //         __asyncLoadCssNew(cssPath, document)
            //       }
            //     }
            //   })
            // } catch (e) {
            //   console.log(' ==== loadFirstAppArr error == ', e)
            // }
          }
          resolve(result)
        }
        // 添加新的监听器
        navigator.serviceWorker.addEventListener('message', window.tech.__preLoadSwMessageListener)
        new Promise((resolve, reject) => {
          const id = Date.now()
          pendingRequests.set(id, { resolve, reject })
          window.iidpSwRegistration.active.postMessage({
            type: 'SW_CONCAT_PATHS',
            data: {
              paths: swConcatPaths,
              delimiter: '/'
            },
            options: {
              concatLoadAppsJsNumber: null, // js最多一次请求个数
              baseUrl
            },
            id: id
          })
        })
      })
    } catch (error) {}
  }
  let env = 'master'
  if (!window.tech) {
    window.tech = {}
  }
  window.tech.env = env
  let apps = {}
  const appsJsonLocalUrl = '/config/apps.json?v=' + new Date().getTime()
  apps = await getFetch(appsJsonLocalUrl)
  try {
    if (apps) {
      window._iidpPreloadApps = apps
    }
    if (apps && 'serviceWorker' in navigator) {
      // console.log(' === iidpPreload  apps ==', apps)
      let collectPathsObj = apps?.preLoadUrl || apps?.global?.preLoadUrl || null
      let preLoadBachNum = apps?.preLoadBachNum || apps?.global?.preLoadBachNum || 2 // 默认3个一批
      // collectPathsObj 结构是 {js:['xx.js','xx.js'],css:['xx.css','xx.css']}
      // 按 preLoadBachNum 分批，生成 collectPathsNew 二维数组，结构如：
      // [{js:['xx.js','xx.js'],css:['xx.css','xx.css']}] 数组里面每项里面 js/css 数组长度最多 preLoadBachNum
      let collectPathsNew = []
      // 分批函数
      const sliceByNum = (arr, num) => {
        const res = []
        for (let i = 0; i < arr.length; i += num) {
          res.push(arr.slice(i, i + num))
        }
        return res
      }
      // 先按类型分批
      const jsBatches = sliceByNum(collectPathsObj.js || [], preLoadBachNum)
      const cssBatches = sliceByNum(collectPathsObj.css || [], preLoadBachNum)
      // 合并成目标结构
      const maxLen = Math.max(jsBatches.length, cssBatches.length)
      for (let i = 0; i < maxLen; i++) {
        collectPathsNew.push({
          js: jsBatches[i] || [],
          css: cssBatches[i] || []
        })
      }
      // console.log(' === collectPathsNew == ', collectPathsNew)
      // console.log(' === collectPathsNew.length == ', collectPathsNew.length)

      for (let i = 0; i < collectPathsNew.length; i++) {
        let collectPaths = collectPathsNew[i]
        if (collectPaths) {
          //   let concatPaths = []
          let swConcatPaths = []
          Object.keys(collectPaths).map((typeKey) => {
            let time = []
            let paths = collectPaths[typeKey].map((it) => {
              let preStr = ''
              let lastStr = ''
              try {
                let sArr = it.split('?')
                preStr = sArr[0] // 去掉其他参数
                lastStr = sArr?.[1]?.split?.('=')?.[1] // 获取等号后面的时间参数
              } catch (e) {}
              time.push(lastStr)
              pathMap.set(preStr, it)
              return preStr
            })
            if (typeKey === 'css' || typeKey === 'js') {
              swConcatPaths.push({
                type: typeKey,
                paths,
                time
              })
            } else {
              //   concatPaths.push({
              //     type: typeKey,
              //     paths,
              //     time
              //   })
            }
          })
          // console.log(' === swConcatPaths == ', i, swConcatPaths)
          await new Promise((resolve) => setTimeout(resolve, 100))
          if (window._iidpPreloadAppsBreak) {
            console.log(
              ' ========== in _iidpPreloadAppsBreak break ==== ',
              window._iidpPreloadAppsBreak
            )
            // 如果已存在监听器，先移除旧的
            if (window.tech.__preLoadSwMessageListener) {
              navigator.serviceWorker.removeEventListener(
                'message',
                window.tech.__preLoadSwMessageListener
              )
              window.tech.__preLoadSwMessageListener = null
            }
            break
          }
          await pollWaitSw()
          // console.log(' === window.iidpSwRegistration == ', window.iidpSwRegistration)
          if (window.iidpSwRegistration) {
            await swReqConcatRes(swConcatPaths)
          }
        }
      }
    }
  } catch (e) {}
}

iidpPreloadRun()
